"""Generate/fill analysis.json for remaining cut videos."""
import json, re, os

BASE = r"C:\Users\renjx\Desktop\Get_Video\data\cc-video"
SCRIPTS = r"C:\Users\renjx\Desktop\Get_Video\scripts"

def parse_vtt(path):
    entries = []
    with open(path, "r", encoding="utf-8") as f:
        lines = f.read().strip().split("\n")
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        m = re.match(r"(\d+:\d+:\d+\.\d+)\s*-->\s*(\d+:\d+:\d+\.\d+)", line)
        if m:
            s, e = m.group(1), m.group(2)
            start = sum(float(x) * [3600,60,1][j] for j,x in enumerate(s.split(":")))
            end = sum(float(x) * [3600,60,1][j] for j,x in enumerate(e.split(":")))
            text_lines = []
            i += 1
            while i < len(lines) and lines[i].strip() and not re.match(r"\d+:\d+:\d+\.\d+\s*-->", lines[i].strip()):
                text_lines.append(lines[i].strip())
                i += 1
            text = " ".join(text_lines)
            if text:
                entries.append({"time": round(start, 3), "endTime": round(end, 3), "text": text})
        else:
            i += 1
    return entries

def read_translations(path):
    with open(path, "r", encoding="utf-8") as f:
        return [line.rstrip("\n") for line in f.readlines()]

def build_analysis(vtt_path, translations, keys, metadata):
    entries = parse_vtt(vtt_path)
    subtitles = []
    for i, entry in enumerate(entries):
        tr = translations[i] if i < len(translations) else ""
        k = keys.get(i, {})
        sub = {
            "time": entry["time"],
            "endTime": entry["endTime"],
            "text": entry["text"],
            "translation": tr,
            "isKeyPoint": bool(k.get("hw")),
            "highlightWords": k.get("hw", []),
            "keyNotes": k.get("kn", {}),
            "highlightTranslations": k.get("ht", {}),
        }
        subtitles.append(sub)
    return {**metadata, "subtitles": subtitles}

def fill_and_save(path, fills):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    for idx, tr in fills.items():
        data["subtitles"][idx]["translation"] = tr
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    empty = sum(1 for s in data["subtitles"] if not s["translation"])
    print(f"  Filled {len(fills)}, remaining empty: {empty}")

def save_analysis(path, data):
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, indent=2)
    total = len(data["subtitles"])
    keys = sum(1 for s in data["subtitles"] if s["isKeyPoint"])
    empty = sum(1 for s in data["subtitles"] if not s["translation"])
    print(f"  Written: {os.path.basename(path)} ({total} subs, {keys} keys, {empty} empty)")

